-- PT109-S4-Q6. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT109-S4-Q6$batch12$ AND q.stimulus=$batch12$A worker for a power company trims the branches of trees that overhang power lines as a prevention against damage to the lines anticipated because of the impending stormy season. The worker reasons that there will be no need for her to trim the overhanging branches of a certain tree because the owners of the tree have indicated that they might cut it down anyway.$batch12$ AND q.prompt=$batch12$Which one of the following decisions is based on flawed reasoning that is most similar to the worker's flawed reasoning?$batch12$ AND q.correct_choice=$batch12$C$batch12$) THEN RAISE EXCEPTION 'Question changed: PT109-S4-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT109-S4-Q6$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S4-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT109-S4-Q6$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$The worker won't trim one tree's branches.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$The owners have said they might cut the tree down.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$"Might" isn't "will." If the tree stays, the lines are at risk. The worker skips needed preventive work based on a possibility.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Skip needed maintenance because the item might be removed.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT109-S4-Q6$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Inspecting the most-used wells first under a time limit is sensible prioritization.$batch12$), ($batch12$B$batch12$, $batch12$Choosing cheaper pipe to save money is a cost tradeoff, not skipping needed work.$batch12$), ($batch12$C$batch12$, $batch12$The van is only "tentatively scheduled" to be junked, yet the mechanic skips its brakes. Same move.$batch12$), ($batch12$D$batch12$, $batch12$The candidate avoids areas where campaigning would actually backfire. That's a reason, not a possibility.$batch12$), ($batch12$E$batch12$, $batch12$Punishing everyone to catch one child is a different flaw.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT109-S4-Q6$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
